-- ─── Integrity constraints ────────────────────────────────────────────────────
-- Times are minutes after local midnight; end ≤ start means the shift crosses midnight.
ALTER TABLE shift_codes
  ADD CONSTRAINT shift_codes_code_format CHECK (length(btrim(code)) BETWEEN 1 AND 6 AND code = btrim(code)),
  ADD CONSTRAINT shift_codes_label_not_blank CHECK (length(btrim(label)) > 0),
  ADD CONSTRAINT shift_codes_color_hex CHECK (color ~ '^#[0-9A-Fa-f]{6}$'),
  ADD CONSTRAINT shift_codes_times_paired CHECK ((start_minute IS NULL) = (end_minute IS NULL)),
  ADD CONSTRAINT shift_codes_start_range CHECK (start_minute BETWEEN 0 AND 1439),
  ADD CONSTRAINT shift_codes_end_range CHECK (end_minute BETWEEN 1 AND 1440),
  ADD CONSTRAINT shift_codes_not_zero_length CHECK (start_minute IS NULL OR start_minute <> end_minute),
  ADD CONSTRAINT shift_codes_break_range CHECK (break_minutes BETWEEN 0 AND 720),
  ADD CONSTRAINT shift_codes_hours_only_for_work CHECK (kind = 'WORK' OR (start_minute IS NULL AND break_minutes = 0));

ALTER TABLE schedule_weeks
  ADD CONSTRAINT schedule_weeks_starts_monday CHECK (extract(isodow FROM week_start) = 1),
  ADD CONSTRAINT schedule_weeks_version_non_negative CHECK (version >= 0);

ALTER TABLE shift_assignments
  ADD CONSTRAINT shift_assignments_date_in_week CHECK (work_date - week_start BETWEEN 0 AND 6),
  ADD CONSTRAINT shift_assignments_color_hex CHECK (color_snapshot ~ '^#[0-9A-Fa-f]{6}$'),
  ADD CONSTRAINT shift_assignments_times_paired CHECK ((start_minute IS NULL) = (end_minute IS NULL)),
  ADD CONSTRAINT shift_assignments_start_range CHECK (start_minute BETWEEN 0 AND 1439),
  ADD CONSTRAINT shift_assignments_end_range CHECK (end_minute BETWEEN 1 AND 1440),
  ADD CONSTRAINT shift_assignments_not_zero_length CHECK (start_minute IS NULL OR start_minute <> end_minute),
  ADD CONSTRAINT shift_assignments_break_range CHECK (break_minutes BETWEEN 0 AND 720),
  ADD CONSTRAINT shift_assignments_custom_time_has_times CHECK (NOT is_custom_time OR start_minute IS NOT NULL),
  ADD CONSTRAINT shift_assignments_hours_only_for_work CHECK (kind_snapshot = 'WORK' OR (start_minute IS NULL AND break_minutes = 0)),
  ADD CONSTRAINT shift_assignments_note_length CHECK (note IS NULL OR length(note) <= 500);

ALTER TABLE schedule_change_sets
  ADD CONSTRAINT schedule_change_sets_changes_array CHECK (jsonb_typeof(changes) = 'array'),
  ADD CONSTRAINT schedule_change_sets_reverts_only_for_undo_redo CHECK ((kind IN ('UNDO', 'REDO')) = (reverts_id IS NOT NULL));

-- ─── Runtime role privileges (least privilege) ────────────────────────────────
-- No DELETE except on shift_assignments (clearing a cell); history lives in change sets,
-- which are append-only (no UPDATE/DELETE).
GRANT SELECT, INSERT, UPDATE ON shift_codes TO rotiqa_app;
GRANT SELECT, INSERT, UPDATE ON schedule_weeks TO rotiqa_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON shift_assignments TO rotiqa_app;
GRANT SELECT, INSERT ON schedule_change_sets TO rotiqa_app;

-- ─── Row Level Security ───────────────────────────────────────────────────────
-- Reuses the F1 helpers (app.current_org_id, app.is_member, app.is_owner,
-- app.can_access_location). No new SECURITY DEFINER functions.
ALTER TABLE shift_codes ENABLE ROW LEVEL SECURITY;
ALTER TABLE schedule_weeks ENABLE ROW LEVEL SECURITY;
ALTER TABLE shift_assignments ENABLE ROW LEVEL SECURITY;
ALTER TABLE schedule_change_sets ENABLE ROW LEVEL SECURITY;

-- shift_codes: every member reads (to plan); only the OWNER creates or edits (UI in F3).
CREATE POLICY shift_codes_select ON shift_codes FOR SELECT TO rotiqa_app
  USING (organization_id = app.current_org_id() AND app.is_member(organization_id));
CREATE POLICY shift_codes_insert ON shift_codes FOR INSERT TO rotiqa_app
  WITH CHECK (organization_id = app.current_org_id() AND app.is_owner(organization_id));
CREATE POLICY shift_codes_update ON shift_codes FOR UPDATE TO rotiqa_app
  USING (organization_id = app.current_org_id() AND app.is_owner(organization_id))
  WITH CHECK (organization_id = app.current_org_id() AND app.is_owner(organization_id));

-- schedule_weeks: anyone who can access the location (OWNER: all, MANAGER: assigned).
CREATE POLICY schedule_weeks_select ON schedule_weeks FOR SELECT TO rotiqa_app
  USING (organization_id = app.current_org_id() AND app.can_access_location(organization_id, location_id));
CREATE POLICY schedule_weeks_insert ON schedule_weeks FOR INSERT TO rotiqa_app
  WITH CHECK (organization_id = app.current_org_id() AND app.can_access_location(organization_id, location_id));
CREATE POLICY schedule_weeks_update ON schedule_weeks FOR UPDATE TO rotiqa_app
  USING (organization_id = app.current_org_id() AND app.can_access_location(organization_id, location_id))
  WITH CHECK (organization_id = app.current_org_id() AND app.can_access_location(organization_id, location_id));

-- shift_assignments: same rule; WITH CHECK also stops moving a row to another location.
CREATE POLICY shift_assignments_select ON shift_assignments FOR SELECT TO rotiqa_app
  USING (organization_id = app.current_org_id() AND app.can_access_location(organization_id, location_id));
CREATE POLICY shift_assignments_insert ON shift_assignments FOR INSERT TO rotiqa_app
  WITH CHECK (organization_id = app.current_org_id() AND app.can_access_location(organization_id, location_id));
CREATE POLICY shift_assignments_update ON shift_assignments FOR UPDATE TO rotiqa_app
  USING (organization_id = app.current_org_id() AND app.can_access_location(organization_id, location_id))
  WITH CHECK (organization_id = app.current_org_id() AND app.can_access_location(organization_id, location_id));
CREATE POLICY shift_assignments_delete ON shift_assignments FOR DELETE TO rotiqa_app
  USING (organization_id = app.current_org_id() AND app.can_access_location(organization_id, location_id));

-- schedule_change_sets: readable with location access; appended only as yourself.
CREATE POLICY schedule_change_sets_select ON schedule_change_sets FOR SELECT TO rotiqa_app
  USING (organization_id = app.current_org_id() AND app.can_access_location(organization_id, location_id));
CREATE POLICY schedule_change_sets_insert ON schedule_change_sets FOR INSERT TO rotiqa_app
  WITH CHECK (
    organization_id = app.current_org_id()
    AND app.can_access_location(organization_id, location_id)
    AND actor_user_id = app.current_user_id()
  );

-- ─── Default shift codes for existing organizations ───────────────────────────
-- Same set new organizations receive at onboarding (shared/utils/shift-codes.ts; colors from
-- shared/design/tokens.ts, kept in sync by tests/unit/scheduling-migration.test.ts).
-- Hours stay empty: each business sets its own A/B/C times. Organizations that already have
-- shift codes are left untouched.
INSERT INTO shift_codes (id, organization_id, code, label, kind, color, sort_order, is_active, created_at, updated_at)
SELECT gen_random_uuid(), o.id, d.code, d.label, d.kind::"ShiftCodeKind", d.color, d.sort_order, true, now(), now()
FROM organizations o
CROSS JOIN (VALUES
  ('A', 'Sabah', 'WORK', '#8EDFE3', 0),
  ('B', 'Ara', 'WORK', '#F8CE67', 1),
  ('C', 'Akşam', 'WORK', '#E77B66', 2),
  ('OFF', 'Haftalık izin', 'OFF', '#F8E4E4', 3),
  ('R', 'Raporlu', 'SICK', '#DC3545', 4),
  ('Y.İ', 'Yıllık izin', 'LEAVE', '#DCCAF5', 5)
) AS d (code, label, kind, color, sort_order)
WHERE NOT EXISTS (SELECT 1 FROM shift_codes s WHERE s.organization_id = o.id);
